function ensureDeviceMainFunction(di,relayId){let d=local.devices?.[di];if(!d)return;let f=mainFunctionForDevice(d);if(!relayId){if(f){d.functionIds=(d.functionIds||[]).filter(id=>id!==f.id);f.enabled=false;f.visible=false;}return}if(!f){let id=uniqueId("sw");f={id,label:d.name||sysText("Schaltung","Switch"),type:"antenna",group:internalSwitchGroupForDevice(d),relayId,enabled:true,visible:true,durationMs:7500,requiresFunctionId:"",stateToken:""};local.functions.push(f);d.functionIds=[...new Set([...(d.functionIds||[]),id])]}else{f.relayId=relayId;f.enabled=true;f.visible=true;if(!f.group)f.group=internalSwitchGroupForDevice(d)}}
