 $$('[data-storm-relay]').forEach(e=>e.onchange=()=>{let d=local.devices?.[+e.dataset.stormRelay];if(!d)return;d.stormRelayId=e.value;scheduleLocalSave()});
 $$('[data-storm-on]').forEach(e=>e.onchange=()=>{let d=local.devices?.[+e.dataset.stormOn];if(!d)return;d.stormRelayOn=e.value==="true";scheduleLocalSave()});
 $$('[data-aux-index][data-aux-k]').forEach(e=>e.onchange=()=>{let f=local.functions?.[+e.dataset.auxIndex];if(!f)return;let k=e.dataset.auxK;if(k==="durationSec")f.durationMs=Math.round(Math.max(.1,Math.min(100,Number(e.value)||.1))*1000);else if(k==="label"){let old=f.label;f.label=e.value;if(!f.stateToken||f.stateToken===old)f.stateToken=e.value.trim()}else f[k]=e.value;scheduleLocalSave()});
 $$('[data-add-aux]').forEach(b=>b.onclick=()=>{addTimedFunctionForDevice(+b.dataset.addAux);renderTab();scheduleLocalSave()});
 $$('[data-del-aux]').forEach(b=>b.onclick=()=>{let f=local.functions?.[+b.dataset.delAux];if(!f||!confirm(sysText(`Zusatzfunktion „${f.label}“ löschen?`,`Delete auxiliary function “${f.label}”?`)))return;removeTimedFunction(+b.dataset.delAux);renderTab();scheduleLocalSave()});
 $$('[data-deldev]').forEach(b=>b.onclick=()=>{let d=local.devices[+b.dataset.deldev];if(!d)return;if(!confirm(`${t("deleteDevice")}: ${d.name||d.id}?`))return;local.devices.splice(+b.dataset.deldev,1);renderTab();scheduleLocalSave()});
 if($('#addDevice'))$('#addDevice').onclick=()=>{let id=uniqueDeviceId(),category="other";local.devices.push({id,name:lang()==="en"?"New device":"Neues Anlagenteil",category,displayGroupId:"middle",bands:[],functionIds:[],enabled:true,exclusive:false,note:""});renderTab();scheduleLocalSave()};
 $$('[data-simple-group-title]').forEach(e=>e.onchange=()=>{let g=shared.displayGroups[+e.dataset.simpleGroupTitle];if(!g)return;g.title=e.value.trim()||g.title;renderTab();scheduleSharedSave()});
 const moveGroup=(idx,dir)=>{let sorted=shared.displayGroups.slice().sort((a,b)=>(Number(a.order)||0)-(Number(b.order)||0)),g=shared.displayGroups[idx],pos=sorted.indexOf(g),to=pos+dir;if(pos<0||to<0||to>=sorted.length)return;[sorted[pos].order,sorted[to].order]=[sorted[to].order,sorted[pos].order];normalizeDisplayGroupOrder();renderTab();scheduleSharedSave()};
 $$('[data-simple-group-up]').forEach(b=>b.onclick=()=>moveGroup(+b.dataset.simpleGroupUp,-1));$$('[data-simple-group-down]').forEach(b=>b.onclick=()=>moveGroup(+b.dataset.simpleGroupDown,1));
 $$('[data-simple-group-del]').forEach(b=>b.onclick=()=>{let g=shared.displayGroups[+b.dataset.simpleGroupDel];if(!g)return;let used=allLogicalDevices().some(d=>d.displayGroupId===g.id);if(used)return toast(sysText("Dieser Bereich wird noch von mindestens einem Anlagenteil benutzt.","This section is still used by at least one device."));if(!confirm(sysText(`Bereich „${g.title}“ löschen?`,`Delete section “${g.title}”?`)))return;shared.displayGroups.splice(+b.dataset.simpleGroupDel,1);normalizeDisplayGroupOrder();renderTab();scheduleSharedSave()});
