 let c=(combined.controllers||[]).find(x=>x.controllerId===d.controllerId);if(!c)return null;
 let ids=new Set(Array.isArray(d.functionIds)?d.functionIds:[]),f=(c.functions||[]).find(x=>ids.has(x.id)&&x.type==="antenna");
 return f?shared.layout.find(x=>x.key===`${d.controllerId}:${f.id}`)||null:null;
