 let verify=await api("/api/shared"),saved=verify.layout?.find(x=>x.key===l.key),expected=r.item||payload;if(!saved||Number(saved.x)!==Number(expected.x)||Number(saved.y)!==Number(expected.y)||Number(saved.w)!==Number(expected.w)||Number(saved.h)!==Number(expected.h)||Number(saved.fontPx)!==Number(expected.fontPx))throw Error(lang()==="en"?"ESP did not confirm the new layout values":"ESP hat die neuen Layoutwerte nicht bestätigt");
