 {let g=geom();for(let gy=0;gy<LAYOUT_ROWS;gy++)for(let gx=0;gx<LAYOUT_COLS;gx++){let c=document.createElement("div");c.className="layout-grid-cell";c.style.left=`${g.pad+gx*g.sx}px`;c.style.top=`${g.pad+gy*g.sy}px`;c.style.width=`${g.cw}px`;c.style.height=`${g.ch}px`;ed.appendChild(c)}}
