function newsHtml(){let rows=(local.news.feeds||[]).map((f,i)=>`<tr><td><input data-ni="${i}" data-nk=enabled type=checkbox ${f.enabled?"checked":""}></td><td><input data-ni="${i}" data-nk=name value="${esc(f.name)}"></td><td><select data-ni="${i}" data-nk=language><option value=de ${f.language==="de"?"selected":""}>DE</option><option value=en ${f.language==="en"?"selected":""}>EN</option></select></td><td><input data-ni="${i}" data-nk=url value="${esc(f.url)}"></td><td><button class=danger data-deln="${i}">×</button></td></tr>`).join("");return `<div class=card><h2>${t("hamNews")}</h2>${check(t("newsActive"),"news.enabled",local.news.enabled)}<div class=grid3><label>${t("newsLanguage")}<select data-path=news.language><option value=de ${local.news.language==="de"?"selected":""}>${t("german")}</option><option value=en ${local.news.language==="en"?"selected":""}>${t("english")}</option></select></label>${field(t("refreshMinutes"),"news.refreshMinutes",local.news.refreshMinutes,"number",'min="30" max="1440"')}${field(t("maxItems"),"news.maxItems",local.news.maxItems,"number",'min="1" max="10"')}</div><div class=table-scroll><table class=table><thead><tr><th>${t("active")}</th><th>${t("name")}</th><th>${t("language")}</th><th>${t("feedUrl")}</th><th></th></tr></thead><tbody>${rows}</tbody></table></div><div class="news-config-actions"><button id=addFeed>${t("addFeed")}</button></div><div id=newsStatus class="news-status small">${t("newsStarting")}</div><p class=small>${t("newsInfo")}</p></div>`}
function bindNews(){bindInputs();$$("[data-ni]").forEach(e=>e.onchange=()=>{let f=local.news.feeds[+e.dataset.ni],k=e.dataset.nk;f[k]=e.type==="checkbox"?e.checked:e.value;scheduleLocalSave()});$$("[data-deln]").forEach(b=>b.onclick=()=>{local.news.feeds.splice(+b.dataset.deln,1);renderTab();scheduleLocalSave()});$("#addFeed").onclick=()=>{local.news.feeds.push({id:"feed"+Date.now(),name:lang()==="en"?"New source":"Neue Quelle",language:local.news.language,url:"",enabled:true});renderTab();scheduleLocalSave()};setTimeout(async()=>{try{let n=await api("/api/news"),e=$("#newsStatus");if(e)e.textContent=n.fetching?t("fetching"):n.lastError?`${t("lastFetch")}: ${n.lastError}`:n.items?.length?`${n.items.length} ${t("loaded")}`:t("noFetch")}catch{}},150)}

const REPORT_ENDPOINT="https://do1anb.de/antennencontroller/melden/";
function errorReportHtml(snap){return `<div class=card><h2>${sysText("Fehler oder Wunsch melden","Report a problem or idea")}</h2><p>${sysText("Du kannst einen Fehler, einen Wunsch oder einen sonstigen Hinweis senden. Vor dem Versand prüfst du den Text noch einmal. Es werden keine WLAN-Daten, Anlagenkonfiguration oder Sicherungen angehängt.","Send a problem, feature idea, or other note. You can review the text before sending. Wi-Fi details, system configuration, and backups are never attached.")}</p><form id=errorReportForm class=report-form><label>${sysText("Art der Meldung","Report type")}<select name=category><option value="Fehler">${sysText("Fehler","Problem")}</option><option value="Wunsch">${sysText("Wunsch / Verbesserungsidee","Feature idea")}</option><option value="Sonstiges">${sysText("Sonstiges","Other")}</option></select></label><label>${sysText("Betreff","Subject")}<input name=subject maxlength=120 required></label><label>${sysText("Was ist passiert oder was wünschst du dir?","What happened or what would you like?")}<textarea name=description maxlength=5000 required rows=5></textarea></label><label>${sysText("Schritte, bei denen der Fehler auftritt (optional)","Steps that reproduce the issue (optional)")}<textarea name=steps maxlength=3000 rows=3></textarea></label><label>${sysText("Was hattest du erwartet? (optional)","What did you expect? (optional)")}<textarea name=expected maxlength=2000 rows=2></textarea></label><label>${sysText("Seit wann oder nach welcher Änderung? (optional)","Since when or after what change? (optional)")}<textarea name=since maxlength=2000 rows=2></textarea></label><label>${sysText("Dein Name (optional)","Your name (optional)")}<input name=name maxlength=100 autocomplete=name></label><label>${sysText("Kontakt für Rückfragen (optional)","Contact for follow-up (optional)")}<input name=contact maxlength=200 autocomplete=email></label><label>${sysText("Mitgesendete Firmware-Version","Firmware version included")}<input value="${esc(snap.firmwareVersion||"")}" disabled></label><input type=hidden name=version value="${esc(snap.firmwareVersion||"")}"><label class=report-consent><input type=checkbox name=consent required><span>${sysText("Ich habe den Text geprüft und möchte ihn über eine verschlüsselte Verbindung an Andreas Bodyn senden.","I reviewed this report and want to send it to Andreas Bodyn over an encrypted connection.")}</span></label><div class=report-actions><button type=submit disabled>${sysText("Bericht prüfen und senden","Review and send report")}</button><button type=button id=saveErrorReport class=secondary>${sysText("Bericht nur herunterladen","Download report only")}</button></div><p id=errorReportStatus class=small aria-live=polite></p><p class=small>${sysText("Der Browser öffnet eine sichere HTTPS-Vorschau. Erst dort wird nach deiner zweiten Bestätigung eine E-Mail verschickt. Falls das nicht klappt, kannst du den Bericht herunterladen. Schreibe keine Passwörter oder privaten Zugangsdaten in den Text.","A secure HTTPS preview opens in a new tab. The email is sent only after your second confirmation there. If that does not work, download the report instead. Do not include passwords or private credentials.")}</p></form></div>`}
function bindErrorReport(){let form=$("#errorReportForm");if(!form)return;let ready=false,sendButton=form.querySelector('button[type="submit"]'),status=$("#errorReportStatus");status.textContent=sysText("Prüfe den sicheren Mailversand …","Checking secure email service …");fetch(`${REPORT_ENDPOINT}?health=1`,{cache:"no-store",mode:"cors"}).then(r=>{if(!r.ok)throw Error();return r.json()}).then(r=>{if(!r.ready)throw Error();ready=true;sendButton.disabled=false;status.textContent=sysText("Sicherer Mailversand erreichbar.","Secure email service is reachable.")}).catch(()=>{status.textContent=sysText("E-Mail-Versand derzeit nicht verfügbar. Du kannst den Bericht lokal herunterladen.","Email service is currently unavailable. You can download the report locally.")});const collect=()=>{let data=Object.fromEntries(new FormData(form).entries());delete data.consent;return {format:"AntennaControllerReportV1",createdAt:new Date().toISOString(),report:data}};$("#saveErrorReport").onclick=()=>{let blob=new Blob([JSON.stringify(collect(),null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`antennensteuerung-bericht-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);status.textContent=sysText("Bericht lokal heruntergeladen. Es wurde nichts versendet.","Report downloaded locally. Nothing was sent.")};form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;if(!ready){status.textContent=sysText("Der Mailversand ist nicht verfügbar. Bitte lade den Bericht herunter.","Email service is unavailable. Please download the report.");return}let report=collect().report,postForm=document.createElement("form");postForm.method="POST";postForm.action=REPORT_ENDPOINT;postForm.target="_blank";for(let [name,value] of Object.entries(report)){let input=document.createElement("input");input.type="hidden";input.name=name;input.value=String(value||"");postForm.appendChild(input)}document.body.appendChild(postForm);postForm.submit();postForm.remove();status.textContent=sysText("Die sichere Vorschau wurde in einem neuen Tab geöffnet.","The secure preview opened in a new tab.")}}
async function loadDiag(){try{let [snap,errs,peers]=await Promise.all([api("/api/snapshot"),api("/api/errors"),api("/api/peers")]);let role=snap.temporaryCoordinator?sysText("Follower · ERSATZMASTER AKTIV","Follower · REPLACEMENT MASTER ACTIVE"):snap.reclaiming?sysText("MASTER · synchronisiert","MASTER · synchronizing"):roleText(snap.systemRole||combined.system?.role||"unassigned");$("#diagBody").innerHTML=`${errorReportHtml(snap)}<div class=card><h2>${t("system")}</h2><div class=grid3><div>${sysText("Rolle","Role")}<br><b>${role}</b></div><div>${t("firmware")}<br><b>v${esc(snap.firmwareVersion||"?")}</b></div><div>${t("build")}<br><b>${esc(formatBuildDate(snap.buildDate||""))}</b></div><div>${t("ip")}<br><b>${esc(snap.ip)}</b></div><div>RSSI<br><b>${snap.rssi} dBm</b></div><div>${t("freeHeap")}<br><b>${snap.heap} B</b></div><div>${t("time")}<br><b>${snap.timeSynced?t("synchronized"):t("notSynchronized")}</b></div><div>${t("uptime")}<br><b>${Math.floor(snap.uptimeMs/1000)} s</b></div><div>ESP-IDF/SDK<br><b>${esc(snap.sdk||"")}</b></div><div>${t("resetReason")}<br><b>${snap.resetReason}</b></div></div></div><div class=card><h2>${t("cluster")}</h2>${peers.length?peers.map(p=>`<div>${esc(p.callSign||"")} · ${esc(p.name)} · ${esc(p.location||"—")} · ${esc(p.ip)} · v${esc(p.firmware||"?")} · <span class=${p.online?"online":"offline"}>${t(p.online?"online":"offline")}</span></div>`).join(""):t("noPeer")}</div><div class=card><h2>${t("errorStore")} (${errs.length}/10)</h2>${errs.length?errs.map(e=>`<div class=err><b>${esc(e.code)}</b> ${esc(e.text)}</div>`):`<p>${t("systemOk")}</p>`}<button id=clearErr class=danger>${t("clearErrors")}</button></div>`;$("#clearErr").onclick=async()=>{await api("/api/errors",{method:"DELETE"});loadDiag()};bindErrorReport()}catch(e){toast(e.message)}}
