function updateHtml(){let self=(combined.controllers||[]).find(c=>c.self)||{},version=self.firmware||self.firmwareVersion||"";return `<div class="card update-safety-card"><h2>${sysText("Programm / Update","Program / Update")}</h2><div class="update-warning"><b>${sysText("Sicherheitsregel: Kein Update ohne Sicherung","Safety rule: no update without a backup")}</b><p>${sysText("Vor jeder Programmaktualisierung erzeugt der ESP automatisch eine geprüfte Sicherung seiner lokalen und gemeinsamen Konfiguration einschließlich WLAN-Zustand.","Before every firmware update the controller automatically creates a verified backup of local/shared configuration including Wi-Fi state.")}</p><p><b>${sysText("Verbund: Diese Datei sichert nur dieses Steuergerät.","Cluster: this file backs up only this controller.")}</b> ${sysText("Für eine vollständige Verbundsicherung jeden ESP über seine eigene Adresse öffnen und dort separat sichern. Die Controller-ID und IP stehen im Dateinamen.","For a complete cluster backup, open each ESP at its own address and save a separate backup there. The controller ID and IP are included in the filename.")}</p></div><div class="update-facts"><span><b>${sysText("Aktuelle Version","Current version")}</b>${esc(version||"-")}</span><span><b>${sysText("Update-Quelle","Update source")}</b>https://github.com/zentrog/ESP32-Antennenschalter-Produkt/releases/latest</span></div>${check(sysText("Programmaktualisierung erlauben","Allow firmware updates"),"features.ota",local.features.ota)}<div id=onlineUpdateState class="online-update-state">${sysText("Onlineprüfung noch nicht ausgeführt.","Online check not run yet.")}</div><div class="update-actions"><button id=checkOnlineUpdate class=secondary>${sysText("Online nach Update suchen","Check online for update")}</button><button id=downloadLatestFirmware class=secondary>${sysText("Neueste Firmware direkt herunterladen","Download the latest firmware directly")}</button><button id=downloadUpdateBackup class=secondary>${sysText("Sicherheitskopie herunterladen","Download safety backup")}</button><button id=openUpdatePage class=secondary ${local.features.ota?"":"disabled"}>${sysText("Manuelles OTA öffnen","Open manual OTA")}</button></div><p class="small">${sysText("Die Onlineprüfung informiert über freigegebene stabile Versionen. Eine Installation wird niemals ohne bewusste Benutzeraktion gestartet. Das manuelle OTA bleibt als Rückfallebene erhalten.","The online check announces released stable versions. Installation is never started without explicit user action. Manual OTA remains available as a fallback.")}</p></div>`}
function summarizeReleaseNotes(raw){const bullets=String(raw||"").replace(/\r/g,"").split("\n").map(line=>line.trim()).filter(line=>/^[-*]\s+/.test(line)).slice(0,2).map(line=>line.replace(/^[-*]\s+/,"").replace(/`/g,"").replace(/\s+/g," ").trim());const summary=bullets.join(" · ");return summary.length>220?summary.slice(0,217).trimEnd()+"…":summary}
async function bindUpdate(){bindInputs();let renderOnline=u=>{let e=$("#onlineUpdateState");if(!e)return;if(u?.error){e.className="online-update-state error";e.textContent=u.error;return}if(!u)return;e.className=`online-update-state ${u.available?"available":"current"}`;const heading=document.createElement("b");heading.textContent=u.available?`${sysText("Neue Version verfügbar","New version available")}: ${u.latest||"?"}`:`${sysText("Installierte Version ist aktuell","Installed version is current")}: ${u.current||""}`;e.replaceChildren(heading);const summary=u.available?summarizeReleaseNotes(u.notes):"";if(summary){const span=document.createElement("span");span.textContent=summary;e.append(span)}};let check=async()=>{let e=$("#onlineUpdateState");if(e)e.textContent=sysText("Prüfe GitHub Releases …","Checking GitHub Releases …");try{renderOnline(await api("/api/update/check"))}catch(x){renderOnline({error:x.message})}};if($("#checkOnlineUpdate"))$("#checkOnlineUpdate").onclick=check;if($("#downloadLatestFirmware"))$("#downloadLatestFirmware").onclick=()=>{location.href="https://github.com/zentrog/ESP32-Antennenschalter-Produkt/releases/latest/download/firmware-esp32dev.bin"};if($("#downloadUpdateBackup"))$("#downloadUpdateBackup").onclick=async()=>{try{await flushLocalSave();if(sharedDirty||savingShared)await saveSharedNow();location.href="/api/update-backup"}catch(e){toast(e.message)}};if($("#openUpdatePage"))$("#openUpdatePage").onclick=async()=>{try{await flushLocalSave();if(sharedDirty||savingShared)await saveSharedNow();window.open("/update","_blank","noopener")}catch(e){toast(e.message)}};setTimeout(check,200)}
function bindSecurity(){if($("#saveSecurity"))$("#saveSecurity").onclick=async()=>{let enabled=$("#adminEnable").checked,user=$("#adminUser").value.trim()||"admin",pw=$("#adminPass").value;shared.security=shared.security||{};shared.security.adminAuthEnabled=enabled;shared.security.adminUser=user;shared.security.adminPassword=pw;markSharedDirty();try{await saveSharedNow();toast(sysText("Anlagenschutz gespeichert","System protection saved"));if(pw)$("#adminPass").value=""}catch(e){toast(e.message)}};$("#backupBtn").onclick=async()=>{try{await flushLocalSave();if(sharedDirty||savingShared)await saveSharedNow();location.href="/api/update-backup"}catch(e){toast(e.message)}};$("#restoreBtn").onclick=()=>$("#restoreFile").click();$("#restoreFile").onchange=async e=>{let f=e.target.files[0];if(!f)return;try{let b=JSON.parse(await f.text()),ok=(b.format==="AntennaControllerBackupV1"||b.format==="AntennaControllerSafetyBackupV2")&&b.local&&b.shared;if(!ok)throw Error(t("backupInvalid"));if(!confirm(t("backupAsk")))return;await post("/api/shared?force=1",b.shared,"PUT");await post(`/api/controller/config?id=${encodeURIComponent(configTarget)}&force=1`,b.local,"PUT");if(b.wifiState)await post("/api/wifi/restore",b.wifiState);toast(sysText("Sicherung vollständig eingespielt.","Backup restored completely."))}catch(ex){toast(ex.message)}};$("#factoryBtn").onclick=async()=>{if(!confirm(t("factoryAsk")))return;try{await post(`/api/controller/factory-reset?id=${encodeURIComponent(configTarget)}`,{})}catch(e){toast(e.message)}}}

